const BASE = "https://ivx-holdings-platform.onrender.com";
const RESULTS: string[] = [];

interface ChatResponse {
  ok: boolean;
  sessionId: string;
  answer: string;
  model: string;
  rateLimitRemaining?: number;
  rateLimitResetAt?: string;
  error?: string;
  commit?: string;
}

async function sendChat(message: string, sessionId?: string): Promise<ChatResponse> {
  const body: Record<string, unknown> = {
    message,
    context: { turnCount: 1 },
  };
  if (sessionId) body.sessionId = sessionId;

  try {
    const resp = await fetch(`${BASE}/public/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(30_000),
    });
    const data = await resp.json() as ChatResponse;
    return data;
  } catch (e) {
    return { ok: false, sessionId: "", answer: "", model: "", error: String(e) };
  }
}

async function sleep(ms: number) {
  return new Promise(r => setTimeout(r, ms));
}

async function test10TurnContext() {
  console.log("\n=== TEST 1: 10-turn context retention ===");
  let sessionId: string | undefined;
  const turns = [
    "Hi, my name is TestUser42 and I'm interested in real estate investing.",
    "What types of investments does IVX offer?",
    "Can you remember my name?",
    "What is my name? If you don't know, say 'I don't know'.",
    "I'm particularly interested in residential properties. What should I know?",
    "Do you remember what I said my interest was?",
    "What is my name and what am I interested in?",
    "Give me a summary of our conversation so far.",
    "What was the first thing I told you?",
    "Final check: what is my name and investment interest?",
  ];

  let passCount = 0;
  let failCount = 0;
  const answers: string[] = [];

  for (let i = 0; i < turns.length; i++) {
    process.stdout.write(`  Turn ${i+1}/${turns.length}: sending... `);
    const resp = await sendChat(turns[i], sessionId);
    if (resp.ok && resp.sessionId) {
      sessionId = resp.sessionId;
      answers.push(resp.answer);
      console.log(`PASS (session=${resp.sessionId.slice(0,8)}, answer_len=${resp.answer.length})`);
      passCount++;
    } else {
      console.log(`FAIL (ok=${resp.ok}, error=${resp.error || resp.answer?.slice(0,50)})`);
      failCount++;
    }
    await sleep(2000); // 2s between turns to respect rate limit
  }

  // Check context retention: turn 3+ should mention "TestUser42"
  const contextCheck1 = answers[2]?.includes("TestUser42") || answers[3]?.includes("TestUser42");
  const contextCheck2 = answers[5]?.includes("TestUser42") || answers[5]?.includes("residential");
  const contextCheck3 = answers[6]?.includes("TestUser42") || answers[6]?.includes("residential");
  const contextCheck4 = answers[8]?.includes("TestUser42") || answers[8]?.includes("real estate");
  const contextCheck5 = answers[9]?.includes("TestUser42") || answers[9]?.includes("residential");

  const contextScore = [contextCheck1, contextCheck2, contextCheck3, contextCheck4, contextCheck5].filter(Boolean).length;

  console.log(`\n  Context retention score: ${contextScore}/5`);
  console.log(`  Turn 3 (name recall): ${contextCheck1 ? "PASS" : "FAIL"}`);
  console.log(`  Turn 6 (interest recall): ${contextCheck2 ? "PASS" : "FAIL"}`);
  console.log(`  Turn 7 (both recall): ${contextCheck3 ? "PASS" : "FAIL"}`);
  console.log(`  Turn 9 (first thing): ${contextCheck4 ? "PASS" : "FAIL"}`);
  console.log(`  Turn 10 (final check): ${contextCheck5 ? "PASS" : "FAIL"}`);
  console.log(`\n  RESULT: ${passCount}/${turns.length} turns OK, context score ${contextScore}/5`);

  const result = passCount === turns.length && contextScore >= 3 ? "PASS" : "FAIL";
  RESULTS.push(`TEST 1 (10-turn context): ${result} (${passCount}/${turns.length} turns, context ${contextScore}/5)`);
  return result;
}

async function testDuplicateRapidSend() {
  console.log("\n=== TEST 2: Duplicate/rapid send (3 identical messages in 1s) ===");
  const msg = "What is IVX?";
  const promises = [
    sendChat(msg),
    sendChat(msg),
    sendChat(msg),
  ];
  const results = await Promise.all(promises);
  let allOk = true;
  let allDifferent = true;
  for (let i = 0; i < results.length; i++) {
    const r = results[i];
    console.log(`  Msg ${i+1}: ok=${r.ok}, answer_len=${r.answer?.length || 0}, error=${r.error || "none"}`);
    if (!r.ok) allOk = false;
  }
  // Check if all 3 responses are different (should be, even for same message)
  const answers = results.map(r => r.answer);
  const uniqueAnswers = new Set(answers);
  console.log(`  Unique answers: ${uniqueAnswers.size}/${answers.length}`);
  if (uniqueAnswers.size === 1) allDifferent = false;

  const result = allOk ? "PASS" : "FAIL";
  RESULTS.push(`TEST 2 (duplicate/rapid send): ${result} (all_ok=${allOk}, unique_answers=${uniqueAnswers.size}/3)`);
  return result;
}

async function testRetryOnFailure() {
  console.log("\n=== TEST 3: Retry on simulated failure (empty message) ===");
  try {
    const resp = await fetch(`${BASE}/public/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message: "", context: { turnCount: 1 } }),
      signal: AbortSignal.timeout(15_000),
    });
    const status = resp.status;
    const body = await resp.text();
    console.log(`  Empty message: status=${status}, body_len=${body.length}`);
    const ok = status === 400 || status === 422 || status === 200;
    console.log(`  Result: ${ok ? "PASS" : "FAIL"} (status=${status})`);
    RESULTS.push(`TEST 3 (empty message handling): ${ok ? "PASS" : "FAIL"} (status=${status})`);
    return ok ? "PASS" : "FAIL";
  } catch (e) {
    console.log(`  Error: ${e}`);
    RESULTS.push(`TEST 3 (empty message handling): FAIL (error=${String(e).slice(0,50)})`);
    return "FAIL";
  }
}

async function testRateLimitEnforcement() {
  console.log("\n=== TEST 4: Rate limit enforcement (22 rapid messages, limit=20/min) ===");
  let ok200 = 0;
  let rateLimited429 = 0;
  let otherStatus = 0;

  for (let i = 0; i < 22; i++) {
    try {
      const resp = await fetch(`${BASE}/public/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: `Rate test ${i}`, context: { turnCount: 1 } }),
        signal: AbortSignal.timeout(10_000),
      });
      if (resp.status === 200) ok200++;
      else if (resp.status === 429) rateLimited429++;
      else otherStatus++;
    } catch {
      otherStatus++;
    }
    // No delay — rapid fire
  }

  console.log(`  Results: 200=${ok200}, 429=${rateLimited429}, other=${otherStatus}`);
  const rateLimitWorks = rateLimited429 > 0 || ok200 <= 20;
  console.log(`  Rate limit enforced: ${rateLimitWorks ? "PASS" : "FAIL"}`);
  RESULTS.push(`TEST 4 (rate limit): ${rateLimitWorks ? "PASS" : "FAIL"} (200=${ok200}, 429=${rateLimited429}, other=${otherStatus})`);
  return rateLimitWorks ? "PASS" : "FAIL";
}

async function testSessionPersistence() {
  console.log("\n=== TEST 5: Session persistence (same sessionId across 5 turns) ===");
  // First message to get a session
  const r1 = await sendChat("I'm tracking deal #12345 worth $5M.");
  if (!r1.ok || !r1.sessionId) {
    console.log(`  First message failed: ok=${r1.ok}`);
    RESULTS.push(`TEST 5 (session persistence): FAIL (first message failed)`);
    return "FAIL";
  }
  const sid = r1.sessionId;
  console.log(`  Session: ${sid.slice(0,8)}, first answer len=${r1.answer.length}`);

  await sleep(2000);

  // Continue with same session
  const r2 = await sendChat("What deal number did I just mention?", sid);
  await sleep(2000);
  const r3 = await sendChat("What was the value I mentioned?", sid);
  await sleep(2000);
  const r4 = await sendChat("Summarize what I've told you so far.", sid);
  await sleep(2000);
  const r5 = await sendChat("What deal number and value did I tell you about?", sid);

  const answers = [r2.answer, r3.answer, r4.answer, r5.answer];
  const has12345 = answers.some(a => a?.includes("12345"));
  const has5M = answers.some(a => a?.includes("5") && (a?.includes("M") || a?.includes("million")));

  console.log(`  Deal #12345 recalled: ${has12345 ? "PASS" : "FAIL"}`);
  console.log(`  $5M value recalled: ${has5M ? "PASS" : "FAIL"}`);

  const result = has12345 || has5M ? "PASS" : "FAIL";
  RESULTS.push(`TEST 5 (session persistence): ${result} (deal_recalled=${has12345}, value_recalled=${has5M})`);
  return result;
}

// Main
async function main() {
  console.log("=== IVX CHAT DEEP QA ===");
  console.log(`Target: ${BASE}`);
  console.log(`Time: ${new Date().toISOString()}`);

  await test10TurnContext();
  await sleep(3000);
  await testDuplicateRapidSend();
  await sleep(3000);
  await testRetryOnFailure();
  await sleep(3000);
  await testRateLimitEnforcement();
  await sleep(5000);
  await testSessionPersistence();

  console.log("\n=== CHAT DEEP QA SUMMARY ===");
  for (const r of RESULTS) console.log(r);

  const passCount = RESULTS.filter(r => r.includes("PASS")).length;
  const failCount = RESULTS.filter(r => r.includes("FAIL")).length;
  console.log(`\nTOTAL: ${passCount} PASS, ${failCount} FAIL out of ${RESULTS.length} tests`);

  // Write results to file
  const { writeFileSync } = await import("fs");
  writeFileSync("/tmp/ivx-chat-deep-qa-results.json", JSON.stringify({
    timestamp: new Date().toISOString(),
    target: BASE,
    tests: RESULTS,
    passCount,
    failCount,
    total: RESULTS.length,
  }, null, 2));
}

main().catch(console.error);
